"""Small live view for paired experimental reports."""
PAGE='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Evolution benchmarks</title><style>
:root{color-scheme:dark}body{font:17px system-ui;background:#101725;color:#eef4ff;max-width:1200px;margin:30px auto;padding:20px}a{color:#7fc4ff}p{color:#b8c5d8;line-height:1.5}article{background:#182438;border:1px solid #344762;border-radius:14px;padding:22px;margin:25px 0}h2{overflow-wrap:anywhere;font-size:23px}table{border-collapse:collapse;width:100%;font-size:15px}td,th{text-align:left;border-bottom:1px solid #344762;padding:12px 8px}th{color:#b8c5d8}.scroll{overflow:auto}.effect{font-size:23px;color:#eef4ff}.small{font-size:14px}progress{width:100%;height:22px;accent-color:#65baff}button{font:inherit;background:#24344d;color:white;border:1px solid #62738e;border-radius:8px;padding:10px;cursor:pointer}
</style><a href="/">Animal playground</a> · <a href="/runs">Training runs</a><h1>Evolution benchmarks</h1>
<p>Paired experiments share initial genotypes, task sequences, mutation settings, elite counts, and evaluation budgets. Only the selected treatment—lifetime learning, learned-weight inheritance, or speciation—is switched on or off.</p>
<p>The primary result tests each run's highest-training saved candidate on fresh shared held-out trials with learned weights frozen. Uncertainty is calculated across paired seeds. Held-out scores do not influence selection.</p>
<button id="refresh">Refresh now</button><p id="connection" role="status">Loading…</p><main id="studies"></main>
<script>
const $=id=>document.getElementById(id),pct=n=>(100*n).toFixed(1)+'%',pp=n=>(n>=0?'+':'')+n.toFixed(2)+' pp';
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function table(headings,rows){const wrap=node('div',undefined,'scroll'),t=node('table'),head=node('tr');headings.forEach(h=>head.append(node('th',h)));const thead=node('thead');thead.append(head);t.append(thead);const body=node('tbody');for(const cells of rows){const row=node('tr');for(const value of cells){const td=node('td');if(value instanceof Node)td.append(value);else td.textContent=value;row.append(td)}body.append(row)}t.append(body);wrap.append(t);return wrap}
let pending=false;
async function refresh(){if(pending)return;pending=true;try{const response=await fetch('/comparisons.json');if(!response.ok)throw Error('Unavailable');const reports=await response.json(),cards=[];for(const r of reports){const treatment=r.treatment||'speciation',controlLabel=r.control_label||'Control',treatmentLabel=r.treatment_label||'Speciation';const card=node('article');card.append(node('h2',r.name),node('p',`${r.status.toUpperCase()} · ${r.population.toLocaleString()} animals per arm · ${r.generations} generations · seeds ${r.seeds.join(', ')}`));const total=r.arms.reduce((n,a)=>n+a.completed,0),target=r.arms.length*r.generations;const progress=node('progress');progress.max=target;progress.value=total;progress.setAttribute('aria-label',`${total} of ${target} total generations complete`);card.append(progress,node('p',`${total}/${target} total generations complete · ${r.episodes} training + ${r.assessment_episodes} assessment episodes per animal · ${r.benchmark_episodes.toLocaleString()} final trials per arm`,'small'));card.append(node('p',`Tasks: ${r.distance_distribution==='normal'?'normal distances, center '+r.distance_mean+', standard deviation '+r.distance_stddev:'uniform valid start/goal pairs'}. Boundaries: ${r.boundary_mode==='clamp'?'hard walls':'original out-of-bounds failure'}. ${treatment==='inheritance'?'Learned-weight inheritance on/off; lifetime learning on in both; speciation disabled.':treatment==='learning'?'Lifetime learning on/off; speciation disabled.':'Speciation: threshold '+r.speciation_threshold+', at most '+r.max_species+' niches.'}`,'small'));
if(r.error)card.append(node('p','Comparison invalid: '+r.error));if(r.paired_effect){const effect=r.paired_effect;card.append(node('p',`${treatmentLabel} − ${controlLabel}: ${pp(effect.mean_percentage_points)} across ${effect.seeds}/${r.seeds.length} completed seed pairs`,'effect'));if(effect.interval95)card.append(node('p',`95% interval across seeds: ${pp(effect.interval95[0])} to ${pp(effect.interval95[1])}`));if(effect.seeds<r.seeds.length)card.append(node('p','Preliminary: remaining seed pairs are still pending.'))}else card.append(node('p',r.error?'No valid comparison result.':'Waiting for the first completed paired final evaluation.'));
card.append(table(['Seed','Matched generations',controlLabel+': fresh held-out',treatmentLabel+': fresh held-out','Difference'],r.pairs.map(p=>[p.seed,p.common_generations,p.control===undefined?'Pending':pct(p.control),p[treatment]===undefined?'Pending':pct(p[treatment]),p.difference_percentage_points===undefined?'—':pp(p.difference_percentage_points)])));
const arms=r.arms.map(a=>{const link=node('a',a.run_name);link.href='/?run='+encodeURIComponent(a.run_name);return[link,a.state,`${a.completed}/${a.target}`,a.latest?pct(a.latest.mean):'—',a.latest?pct(a.latest.assessment_mean):'—',a.latest?a.latest.species_count:'—',a.latest?a.latest.unique_structures:'—',a.final_benchmark?pct(a.final_benchmark.random.success_rate):'—']});card.append(node('p','Latest population diagnostics and links to test each run’s best candidate:','small'),table(['Run','State','Generations','Mean training','Population held-out','Species','Unique structures','Final random'],arms));cards.push(card)}$('studies').replaceChildren(...cards);$('connection').textContent=`Updated ${new Date().toLocaleTimeString()}`+(reports.length?'':' · No comparisons yet.')}catch(e){$('connection').textContent='Connection lost. Retaining the last report; retrying every 5 seconds.'}finally{pending=false}}
$('refresh').onclick=refresh;refresh();setInterval(refresh,5000);
</script></html>'''
